import{_ as r,a0 as l,w as d,s as p,ao as i,I as a,x as t,a1 as n,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"学习在 Linux 上使用 JOE 文本编辑器 | LCTT x X-CMD","titleTemplate":false,"description":"学习在 Linux 上使用 JOE 文本编辑器 | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"学习在 Linux 上使用 JOE 文本编辑器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"学习在 Linux 上使用 JOE 文本编辑器 | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20201228 Learn to use the JOE text editor on Linux","title":"学习在 Linux 上使用 JOE 文本编辑器","tag":"202101","desc":""},"relativePath":"202101/20201228 Learn to use the JOE text editor on Linux.md","filePath":"[post].md"}'),u={name:"202101/20201228 Learn to use the JOE text editor on Linux.md"};function m(E,e,f,x,g,J){const o=l("Link");return d(),p("div",null,[e[21]||(e[21]=i('<h1 id="学习在-linux-上使用-joe-文本编辑器" tabindex="-1">学习在 Linux 上使用 JOE 文本编辑器 <a class="header-anchor" href="#学习在-linux-上使用-joe-文本编辑器" aria-label="Permalink to “学习在 Linux 上使用 JOE 文本编辑器”">​</a></h1><blockquote><p>Joe&#39;s Own Editor （JOE）是一款简单易学和使用的通用文本编辑器。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202101/07/233204ps2fl3fffgmxzxqg.jpg" alt=""></p><p>我很喜欢那些能让你轻松学会如何使用的文本编辑器。GNU nano 是我最喜欢的例子：你启动 nano，你会在整个会话的窗口底部看到一个最常用的命令列表。Joe&#39;s Own Editor（简称 <code>joe</code>）是另一个很好的例子。</p><p><code>joe</code> 编辑器使用了一个基于终端的界面，提供了简单的文本编辑功能和一个易于访问的帮助屏幕。它用 C 语言编写，体积小，只对 libc 有硬性依赖（ncurses 是可选的），并且采用 GPL 许可证。</p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h3>',6)),a("p",null,[e[1]||(e[1]=t("在 Linux 上，你也许能在你的发行版软件仓库中找到 JOE。虽然它有点小众，并不是所有的发行版都打包了它。如果是这样的话，你可以从 ",-1)),n(o,{href:"https://joe-editor.sourceforge.io/"},{default:s(()=>[...e[0]||(e[0]=[t("SourceForge",-1)])]),_:1}),e[2]||(e[2]=t(" 下载源码，然后自己编译。这是个简单的过程：",-1))]),e[22]||(e[22]=i(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./configure</span></span>
<span class="line"><span>$ make</span></span>
<span class="line"><span>$ sudo make install</span></span></code></pre></div><h3 id="使用-joe" tabindex="-1">使用 JOE <a class="header-anchor" href="#使用-joe" aria-label="Permalink to “使用 JOE”">​</a></h3>`,2)),a("p",null,[e[4]||(e[4]=t("据其作者介绍，JOE 的灵感来自于一个叫 WordStar 的应用和 ",-1)),n(o,{href:"https://opensource.com/article/20/12/emacs"},{default:s(()=>[...e[3]||(e[3]=[t("GNU Emacs",-1)])]),_:1}),e[5]||(e[5]=t("。它的大部分基本编辑键都与 WordStar 的快捷键相同，编辑器本身也在努力向 WordStar 靠拢。JOE 也有 GNU Emacs 的一些键绑定和功能。这种两种灵感来源的混合有时会让人迷惑，但话又说回来，在任何情况下，让自己离开 Emacs（或你通常选择的文本编辑器）都会让人迷惑。重要的是，JOE 提供了帮助，而且很容易访问。",-1))]),e[23]||(e[23]=i('<p>在 JOE 界面右上角，有一个持续的提示，你可以按 <code>Ctrl+K</code>，紧接着按 <code>H</code> 来查看帮助界面。这是一个切换键，所以一旦你激活它，帮助屏幕就会一直显示在你的编辑器窗口顶部，直到用同样的组合键（JOE 中的键盘符号为 <code>^KH</code>）解除。</p><h3 id="键盘快捷键" tabindex="-1">键盘快捷键 <a class="header-anchor" href="#键盘快捷键" aria-label="Permalink to “键盘快捷键”">​</a></h3><p>尽管 JOE 的作者在模拟 WordStar 用户体验方面非常自豪，但我不得不承认，这对我来说是失落的。我从来没有听说过 WordStar，直到我在 JOE 的文档中读到了它，在我看来，它的键盘快捷键方案完全是任意的。有的用 <code>Ctrl+K</code> 作为转义序列的前缀，有的用 <code>Esc</code> 作为前缀，还有的完全不需要转义序列。我无法确定其中的逻辑。编辑操作和应用选项一样，都有可能需要或不需要转义序列，而且字母关联对我来说是没有什么意义（例如，<code>Ctrl+K D</code> 代表<strong>另存为</strong>）。</p><p>幸运的是，JOE 可以让你在键盘快捷键上作弊。安装后，JOE 会悄悄为 <code>joe</code> 可执行文件创建一些符号链接。包括：</p><ul><li><code>jmacs</code> JOE 使用 Emacs 键绑定</li><li><code>jpico</code> JOE 使用 Pico （或 GNU nano） 键绑定</li><li><code>rjoe</code> JOE 的编辑只限于启动时传递给 JOE 的文件</li><li><code>jstar</code> JOE 使用 WordStar 键绑定</li></ul><p><img src="https://opensource.com/sites/default/files/uploads/joe-jstar-31_days-joe-opensource.png" alt="Black terminal with white text showing WordStar key bindings" title="Black terminal with white text showing WordStar key bindings"></p><p>持久保留的帮助菜单仍然存在，所以如果你不清楚有哪些功能可以使用，可以通过屏幕右上方的帮助提示来参考。当然，在 Pico/nano 模式下，主要命令总是可见的。</p><h3 id="尝试-joe" tabindex="-1">尝试 JOE <a class="header-anchor" href="#尝试-joe" aria-label="Permalink to “尝试 JOE”">​</a></h3><p>JOE 并不是一个你永远不会离开的文本编辑器，它不会成为你的 IDE、电子邮件客户端、网络浏览器和文件管理器。事实上，它甚至可能不是你所有任务的主要文本编辑器。它专注于做好一件事，那就是成为一般的文本编辑。</p><p>JOE 拥有你所需要的所有基本功能，比如能够快速浏览你的文本、能够选择文本、复制和粘贴等等。试试 JOE 吧，使用你喜欢的符号链接。</p><hr>',11)),a("p",null,[e[7]||(e[7]=t("via: ",-1)),n(o,{href:"https://opensource.com/article/20/12/joe"},{default:s(()=>[...e[6]||(e[6]=[t("https://opensource.com/article/20/12/joe",-1)])]),_:1})]),a("p",null,[e[12]||(e[12]=t("作者：",-1)),n(o,{href:"https://opensource.com/users/seth"},{default:s(()=>[...e[8]||(e[8]=[t("Seth Kenlon",-1)])]),_:1}),e[13]||(e[13]=t(" 选题：",-1)),n(o,{href:"https://github.com/lujun9972"},{default:s(()=>[...e[9]||(e[9]=[t("lujun9972",-1)])]),_:1}),e[14]||(e[14]=t(" 译者：",-1)),n(o,{href:"https://github.com/geekpi"},{default:s(()=>[...e[10]||(e[10]=[t("geekpi",-1)])]),_:1}),e[15]||(e[15]=t(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:s(()=>[...e[11]||(e[11]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[18]||(e[18]=t("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原创编译，",-1)),n(o,{href:"https://linux.cn/"},{default:s(()=>[...e[17]||(e[17]=[t("Linux中国",-1)])]),_:1}),e[20]||(e[20]=t(" 荣誉推出",-1))])])}const k=r(u,[["render",m]]);export{h as __pageData,k as default};
